const has = (q, ws) => ws.some(w => q.includes(w));
/* insurance first for anything that may become a claim; numbers for the place; the mission for documents */
function emergencyInfo(topic) {
  const q = String(topic || '').toLowerCase();
  const claim = has(q, ['мед', 'бол', 'трав', 'врач', 'больниц', 'скор', 'дтп', 'авари', 'несчаст', 'укус', 'аптек', 'зуб', 'багаж', 'чемодан', 'задерж', 'рейс', 'стыков',
    'отмен', 'краж', 'укра', 'потер', 'страх', 'insur', 'medic', 'hospital', 'baggage', 'luggage', 'delay', 'theft', 'stolen', 'accident']);
  const china = has(q, ['китай', 'шанха', 'china', 'shanghai', 'пудун']);
  const passport = has(q, ['паспорт', 'посольств', 'консул', 'passport', 'embassy']);
  const keys = [];
  if (claim) keys.push('insurance');
  keys.push(china ? 'china' : 'japan');
  if (passport || (!claim && has(q, ['документ', 'виз']))) keys.push('kazakhstan');
  if (!claim && !passport && !china && keys.length === 1) keys.push('insurance', 'kazakhstan');   // a vague question: everything, insurance before the mission
  return `(справка от ${KB_DATE})\n` + [...new Set(keys)].map(k => `${KB[k].title}:\n${KB[k].text}`).join('\n\n');
}
function cardPerks(topic) {
  const q = String(topic || '').toLowerCase();
  const lines = KB.card.text.split('\n');
  const pick = has(q, ['зал', 'lounge']) ? [0] : has(q, ['консьерж', 'ресторан', 'concierge']) ? [1] : has(q, ['esim', 'сим', 'интернет', 'связь', 'roam']) ? [2]
    : has(q, ['курс', 'валют', 'dcc', 'тенге', 'kzt', 'конверт']) ? [3] : has(q, ['налич', 'банкомат', 'atm', 'снять', 'снят']) ? [4] : has(q, ['бонус', 'кешбэк', 'кэшбэк', 'cashback']) ? [5] : null;
  const body = pick ? pick.map(i => lines[i]).concat(lines[6]).join('\n') : KB.card.text;
  return `${KB.card.title} (справка от ${KB_DATE}):\n${body}`;
}

