    const note = text(a.note, 500, 'note', false); if (note.error) return note;
    const num = (v, lim) => v == null ? null : typeof v === 'number' && Number.isFinite(v) && Math.abs(v) <= lim ? Math.round(v * 1e5) / 1e5 : NaN;
