    const hits = [...idx.stops.values()].filter(x => [x.t, x.place, x.loc, x.note].some(v => String(v || '').toLowerCase().includes(q))).slice(0, 15);
    return { content: hits.length ? hits.map(x => `День ${x.day}:` + stopLine(x)).join('\n') : 'Ничего не нашлось.' };
