    const r = idx.recipes.map(x => `- ${x.what}${x.buy_by ? ' · купить до ' + x.buy_by : ''}${x.opens ? ' · продажи: ' + x.opens : ''}${x.site ? ' · ' + x.site : ''}${x.price_pp ? ' · ¥' + x.price_pp + '/чел' : ''}${x.tips ? ' · ' + x.tips : ''}`).join('\n');
